using MySqlConnector; using System.Security.Cryptography;
using LabLedger.Models;
namespace LabLedger.Data;
public sealed class UserRepository
{
 public bool Validate(string username,string password) { using var c=DatabaseHelper.OpenConnection(); using var q=c.CreateCommand(); q.CommandText="SELECT PasswordHash,Salt FROM Users WHERE Username=@u"; q.Parameters.AddWithValue("@u",username); using var r=q.ExecuteReader(); return r.Read() && CryptographicOperations.FixedTimeEquals(Convert.FromHexString(r.GetString(0)),Convert.FromHexString(DatabaseHelper.Hash(password,r.GetString(1)))); }
}
public sealed class EquipmentRepository
{
 private static Equipment Read(MySqlDataReader r)=>new(){Id=r.GetInt32(0),Name=r.GetString(1),AssetId=r.GetString(2),Category=r.GetString(3),Lab=r.GetString(4),TotalQuantity=r.GetInt32(5),AvailableQuantity=r.GetInt32(6)};
 public bool AssetExists(string id){using var c=DatabaseHelper.OpenConnection();using var q=c.CreateCommand();q.CommandText="SELECT EXISTS(SELECT 1 FROM Equipment WHERE LOWER(AssetId)=LOWER(@id))";q.Parameters.AddWithValue("@id",id);return Convert.ToInt32(q.ExecuteScalar())!=0;}
 public void Add(Equipment e){using var c=DatabaseHelper.OpenConnection();using var q=c.CreateCommand();q.CommandText="INSERT INTO Equipment(Name,AssetId,Category,Lab,TotalQuantity,AvailableQuantity) VALUES(@n,@a,@c,@l,@t,@v)";q.Parameters.AddWithValue("@n",e.Name);q.Parameters.AddWithValue("@a",e.AssetId);q.Parameters.AddWithValue("@c",e.Category);q.Parameters.AddWithValue("@l",e.Lab);q.Parameters.AddWithValue("@t",e.TotalQuantity);q.Parameters.AddWithValue("@v",e.TotalQuantity);q.ExecuteNonQuery();}
 public List<Equipment> GetAll(string search=""){using var c=DatabaseHelper.OpenConnection();using var q=c.CreateCommand();q.CommandText="SELECT Id,Name,AssetId,Category,Lab,TotalQuantity,AvailableQuantity FROM Equipment WHERE @s='' OR Name LIKE @like OR AssetId LIKE @like OR Category LIKE @like ORDER BY Name";q.Parameters.AddWithValue("@s",search);q.Parameters.AddWithValue("@like",$"%{search}%");using var r=q.ExecuteReader();var list=new List<Equipment>();while(r.Read())list.Add(Read(r));return list;}
 public Equipment? Get(int id,MySqlConnection? c=null,MySqlTransaction? tx=null){bool own=c is null;c??=DatabaseHelper.OpenConnection();try{using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="SELECT Id,Name,AssetId,Category,Lab,TotalQuantity,AvailableQuantity FROM Equipment WHERE Id=@id";q.Parameters.AddWithValue("@id",id);using var r=q.ExecuteReader();return r.Read()?Read(r):null;}finally{if(own)c.Dispose();}}
 public void Delete(int id){using var c=DatabaseHelper.OpenConnection();using var tx=c.BeginTransaction();using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="DELETE FROM Loans WHERE EquipmentId=@id";q.Parameters.AddWithValue("@id",id);q.ExecuteNonQuery();}using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="DELETE FROM Equipment WHERE Id=@id";q.Parameters.AddWithValue("@id",id);q.ExecuteNonQuery();}tx.Commit();}
}
public sealed class LoanRepository
{
 public void Borrow(int equipId,string student,int qty){using var c=DatabaseHelper.OpenConnection();using var tx=c.BeginTransaction();using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="UPDATE Equipment SET AvailableQuantity=AvailableQuantity-@q WHERE Id=@id AND AvailableQuantity>=@q";q.Parameters.AddWithValue("@q",qty);q.Parameters.AddWithValue("@id",equipId);if(q.ExecuteNonQuery()!=1)throw new InvalidOperationException("There are not enough units available.");}using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="INSERT INTO Loans(EquipmentId,StudentId,QuantityBorrowed,QuantityReturned,BorrowedAt) VALUES(@id,@s,@q,0,@at)";q.Parameters.AddWithValue("@id",equipId);q.Parameters.AddWithValue("@s",student);q.Parameters.AddWithValue("@q",qty);q.Parameters.AddWithValue("@at",DateTime.UtcNow.ToString("O"));q.ExecuteNonQuery();}tx.Commit();}
 public void Return(int equipId,string student,int qty){using var c=DatabaseHelper.OpenConnection();using var tx=c.BeginTransaction();using var sum=c.CreateCommand();sum.Transaction=tx;sum.CommandText="SELECT COALESCE(SUM(QuantityBorrowed-QuantityReturned),0) FROM Loans WHERE EquipmentId=@id AND StudentId=@s";sum.Parameters.AddWithValue("@id",equipId);sum.Parameters.AddWithValue("@s",student);if(Convert.ToInt32(sum.ExecuteScalar())<qty)throw new InvalidOperationException("This student does not have that many units on loan.");var left=qty;using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="SELECT Id,QuantityBorrowed-QuantityReturned FROM Loans WHERE EquipmentId=@id AND StudentId=@s AND QuantityBorrowed>QuantityReturned ORDER BY BorrowedAt,Id";q.Parameters.AddWithValue("@id",equipId);q.Parameters.AddWithValue("@s",student);using var r=q.ExecuteReader();var rows=new List<(int,int)>();while(r.Read())rows.Add((r.GetInt32(0),r.GetInt32(1)));r.Close();foreach(var row in rows){int take=Math.Min(left,row.Item2);using var upd=c.CreateCommand();upd.Transaction=tx;upd.CommandText="UPDATE Loans SET QuantityReturned=QuantityReturned+@q WHERE Id=@id";upd.Parameters.AddWithValue("@q",take);upd.Parameters.AddWithValue("@id",row.Item1);upd.ExecuteNonQuery();left-=take;if(left==0)break;}}using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="UPDATE Equipment SET AvailableQuantity=MIN(TotalQuantity,AvailableQuantity+@q) WHERE Id=@id";q.Parameters.AddWithValue("@q",qty);q.Parameters.AddWithValue("@id",equipId);q.ExecuteNonQuery();}tx.Commit();}
}
public sealed class StatisticsRepository
{
 public EquipmentStatistics Get(){using var c=DatabaseHelper.OpenConnection();var s=new EquipmentStatistics();using(var q=c.CreateCommand()){q.CommandText="SELECT COUNT(*),COALESCE(SUM(TotalQuantity),0),COALESCE(SUM(TotalQuantity-AvailableQuantity),0),COALESCE(SUM(CASE WHEN AvailableQuantity=0 THEN 1 ELSE 0 END),0) FROM Equipment";using var r=q.ExecuteReader();if(r.Read()){s.TotalItems=r.GetInt32(0);s.TotalUnits=r.GetInt32(1);s.OnLoan=r.GetInt32(2);s.OutOfStock=r.GetInt32(3);}}using(var q=c.CreateCommand()){q.CommandText="SELECT e.Name,SUM(l.QuantityBorrowed-l.QuantityReturned) n FROM Loans l JOIN Equipment e ON e.Id=l.EquipmentId GROUP BY e.Id HAVING n>0 ORDER BY n DESC LIMIT 1";using var r=q.ExecuteReader();if(r.Read())s.MostBorrowed=$"{r.GetString(0)} ({r.GetInt32(1)} units)";}return s;}
}
